/**
 * Tab 2 — Thống kê phân tích sự cố (Phụ lục IV a)
 *
 * Charts (parity bd-2):
 *  • Row 1 — Quy trình liên quan (pie) · Té ngã · Nhầm dịch vụ (doughnut)
 *  • Row 2 — Nhóm loại sự cố · Nhóm nguyên nhân
 */
import React, { useCallback, useState } from 'react';
import {
  Chart as ChartJS,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { ChartEvent, ActiveElement } from 'chart.js';
import { Doughnut, Pie } from 'react-chartjs-2';
import { MedicalIncidentReport, ChartDataItem, MedicalIncidentReportFilters } from '../../../models/MedicalIncident';
import {
  CHART_COLORS,
  DOUGHNUT_OPTIONS,
  buildBaseDateListUrl,
} from '../chartUtils';
import { ChartViewListPopover, ChartPopoverState } from './ChartViewListPopover';
import s from './shared.module.css';

ChartJS.register(ArcElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
  filters: MedicalIncidentReportFilters;
}

const YES_NO_COLORS = ['#ec4899', '#10b981']; // Có · Không

const ClickHint: React.FC = () => (
  <span
    title="Nhấn vào phần để xem danh sách"
    style={{ marginLeft: 6, fontSize: '0.7rem', color: '#94a3b8', fontWeight: 400, cursor: 'default' }}
  >
    <i className="fas fa-hand-pointer" />
  </span>
);

const ChartEmpty: React.FC<{ message?: string }> = ({ message = 'Chưa có dữ liệu trong kỳ đã chọn' }) => (
  <div className={s.emptyState}>
    <i className="fas fa-chart-pie" />
    {message}
  </div>
);

const hasData = (items: ChartDataItem[]) => items.some((d) => d.count > 0);

const toYesNoArc = (items: ChartDataItem[]) => ({
  labels: items.map((d) => d.label),
  datasets: [
    {
      data: items.map((d) => d.count),
      backgroundColor: items.map((d) =>
        d.key === 'yes' || d.key === 'true' ? YES_NO_COLORS[0] : YES_NO_COLORS[1],
      ),
      borderWidth: 2,
      borderColor: '#fff',
    },
  ],
});

const toGroupDoughnut = (items: ChartDataItem[]) => {
  const visible = items.filter((d) => d.count > 0);
  return {
    labels: visible.map((d) => d.label),
    datasets: [
      {
        data: visible.map((d) => d.count),
        backgroundColor: CHART_COLORS.slice(0, Math.max(visible.length, 1)),
        borderWidth: 2,
        borderColor: '#fff',
      },
    ],
    _items: visible,
  };
};

export const Tab2Analysis: React.FC<Props> = ({ report, filters }) => {
  const [popover, setPopover] = useState<ChartPopoverState | null>(null);
  const closePopover = useCallback(() => setPopover(null), []);

  const makeClickHandler = (
    items: ChartDataItem[],
    hintBuilder: (item: ChartDataItem) => string,
  ) => (chartEvent: ChartEvent, elements: ActiveElement[]) => {
    if (!elements.length) { setPopover(null); return; }
    const idx  = elements[0].index;
    const item = items[idx];
    if (!item || item.count === 0) { setPopover(null); return; }
    const native = chartEvent.native as MouseEvent;
    setPopover({
      x:          native.clientX,
      y:          native.clientY,
      label:      item.label,
      filterHint: hintBuilder(item),
      listUrl:    buildBaseDateListUrl(filters),
    });
  };

  const related  = report.byRelatedProcess ?? [];
  const fall     = report.byFallIncident ?? [];
  const mismatch = report.byServiceMismatch ?? [];
  const typeGroup = toGroupDoughnut(report.byIncidentTypeGroup ?? []);
  const causeGroup = toGroupDoughnut(report.byCauseGroup ?? []);

  const doughnutOptSmall = {
    ...DOUGHNUT_OPTIONS,
    plugins: {
      ...DOUGHNUT_OPTIONS.plugins,
      legend: {
        position: 'bottom' as const,
        labels: { font: { size: 11 }, padding: 8, boxWidth: 12 },
      },
    },
  };

  const pieOpt = {
    ...doughnutOptSmall,
    cutout: 0,
  };

  const doughnutOptLarge = {
    ...DOUGHNUT_OPTIONS,
    plugins: {
      ...DOUGHNUT_OPTIONS.plugins,
      legend: {
        position: 'right' as const,
        labels: { font: { size: 11 }, padding: 8, boxWidth: 12 },
      },
    },
  };

  return (
    <div>
      {popover && <ChartViewListPopover {...popover} onClose={closePopover} />}

      <div className={s.sectionBanner}>
        <p className={s.sectionBannerTitle}>Phân loại sự cố y khoa</p>
        <p className={s.sectionBannerSub}>Theo Phụ lục IV a, Thông tư 43/2018/TT-BYT</p>
      </div>

      <div className={s.grid3} style={{ marginBottom: 16 }}>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 1.</span>
            Quy trình liên quan sự cố
            <ClickHint />
          </h3>
          <div className={s.chartBody}>
            {hasData(related) ? (
              <Pie
                data={toYesNoArc(related)}
                options={{
                  ...pieOpt,
                  onClick: makeClickHandler(related, (item) => `Quy trình liên quan: ${item.label} — ${item.count} sự cố`),
                }}
              />
            ) : (
              <ChartEmpty />
            )}
          </div>
        </div>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 2.</span>
            Sự cố té ngã
            <ClickHint />
          </h3>
          <div className={s.chartBody}>
            {hasData(fall) ? (
              <Doughnut
                data={toYesNoArc(fall)}
                options={{
                  ...doughnutOptSmall,
                  onClick: makeClickHandler(fall, (item) => `Té ngã: ${item.label} — ${item.count} sự cố`),
                }}
              />
            ) : (
              <ChartEmpty />
            )}
          </div>
        </div>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 3.</span>
            Cung cấp nhầm dịch vụ
            <ClickHint />
          </h3>
          <div className={s.chartBody}>
            {hasData(mismatch) ? (
              <Doughnut
                data={toYesNoArc(mismatch)}
                options={{
                  ...doughnutOptSmall,
                  onClick: makeClickHandler(mismatch, (item) => `Nhầm dịch vụ: ${item.label} — ${item.count} sự cố`),
                }}
              />
            ) : (
              <ChartEmpty />
            )}
          </div>
        </div>
      </div>

      <div className={s.grid2}>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 4.</span>
            Phân loại theo nhóm sự cố
            <ClickHint />
          </h3>
          <div className={`${s.chartBody} ${s.chartBodyLarge}`}>
            {hasData(typeGroup._items) ? (
              <Doughnut
                data={typeGroup}
                options={{
                  ...doughnutOptLarge,
                  onClick: makeClickHandler(
                    typeGroup._items,
                    (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
                  ),
                }}
              />
            ) : (
              <ChartEmpty message="Chưa có phân tích nhóm sự cố (Tab 4A)" />
            )}
          </div>
        </div>
        <div className={s.chartCard}>
          <h3>
            <span className={s.figNum}>Hình 5.</span>
            Phân loại theo nhóm nguyên nhân
            <ClickHint />
          </h3>
          <div className={`${s.chartBody} ${s.chartBodyLarge}`}>
            {hasData(causeGroup._items) ? (
              <Doughnut
                data={causeGroup}
                options={{
                  ...doughnutOptLarge,
                  onClick: makeClickHandler(
                    causeGroup._items,
                    (item) => `${item.label} — xem danh sách trong khoảng thời gian đã chọn`,
                  ),
                }}
              />
            ) : (
              <ChartEmpty message="Chưa có phân tích nhóm nguyên nhân (Tab 4A)" />
            )}
          </div>
        </div>
      </div>
    </div>
  );
};
