/**
 * Tab 5 — Thống kê theo nhóm nguyên nhân gây ra
 *
 * Shows 4 cause group cards with detail tables.
 */
import React, { useState } from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Tooltip,
  Legend,
} from 'chart.js';
import { Bar } from 'react-chartjs-2';
import { MedicalIncidentReport, GroupDetail } from '../../../models/MedicalIncident';
import { CHART_COLORS, BAR_OPTIONS_HORIZONTAL } from '../chartUtils';
import s from './shared.module.css';

ChartJS.register(CategoryScale, LinearScale, BarElement, Tooltip, Legend);

interface Props {
  report: MedicalIncidentReport;
}

interface CauseGroupCardProps {
  group: GroupDetail;
  colorIndex: number;
}

const CauseGroupCard: React.FC<CauseGroupCardProps> = ({ group, colorIndex }) => {
  const [open, setOpen] = useState(group.totalCount > 0);
  const hasData = group.totalCount > 0;

  const barData = {
    labels: group.items.map((i) => i.label),
    datasets: [
      {
        label: 'Số ca',
        data: group.items.map((i) => i.count),
        backgroundColor: CHART_COLORS[colorIndex % CHART_COLORS.length],
        borderRadius: 4,
      },
    ],
  };

  return (
    <div className={s.groupCard}>
      <div className={s.groupHeader} onClick={() => setOpen((p) => !p)}>
        <div className={s.groupHeaderLeft}>
          <span
            style={{
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              width: 28, height: 28, borderRadius: '50%',
              background: hasData ? CHART_COLORS[colorIndex % CHART_COLORS.length] : '#e2e8f0',
              color: '#fff',
              fontSize: '0.75rem', fontWeight: 700,
            }}
          >
            {colorIndex + 1}
          </span>
          <span className={s.groupLabel}>{group.groupLabel}</span>
          {hasData ? (
            <span className={s.groupBadge}>{group.totalCount} sự cố</span>
          ) : (
            <span
              style={{
                fontSize: '0.72rem', color: '#94a3b8',
                background: '#f1f5f9', borderRadius: 999, padding: '2px 8px',
              }}
            >
              Không có
            </span>
          )}
        </div>
        <i className={`fas fa-chevron-down ${s.groupChevron} ${open ? s.open : ''}`} />
      </div>

      {open && (
        <div style={{ padding: '16px' }}>
          {!hasData ? (
            <div className={s.emptyState}>
              <i className="fas fa-check-circle" style={{ color: '#10b981', marginRight: 6 }} />
              Không ghi nhận nguyên nhân trong nhóm này
            </div>
          ) : (
            <div className={s.grid2}>
              {/* Table */}
              <table className={s.detailTable}>
                <thead>
                  <tr>
                    <th>Nguyên nhân</th>
                    <th style={{ textAlign: 'right', width: 80 }}>Số ca</th>
                  </tr>
                </thead>
                <tbody>
                  {group.items.map((item) => (
                    <tr key={item.key}>
                      <td>{item.label}</td>
                      <td className={`${s.countCell} ${item.count === 0 ? s.zeroCount : ''}`}>
                        {item.count === 0 ? '–' : item.count}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {/* Mini bar chart */}
              <div>
                <Bar
                  data={barData}
                  options={{
                    ...BAR_OPTIONS_HORIZONTAL,
                    plugins: {
                      ...BAR_OPTIONS_HORIZONTAL.plugins,
                      legend: { display: false },
                    },
                  }}
                />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export const Tab5ByCauseGroup: React.FC<Props> = ({ report }) => {
  const totalCausedGroups = report.causeGroupDetails.filter((g) => g.totalCount > 0).length;

  return (
    <div>
      {/* Summary header */}
      <div
        style={{
          display: 'flex', alignItems: 'center', gap: 16, marginBottom: 16,
          padding: '12px 16px',
          background: '#fdf4ff',
          borderRadius: 10,
          border: '1px solid #e9d5ff',
          flexWrap: 'wrap',
        }}
      >
        <div>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Nhóm nguyên nhân có ghi nhận</span>
          <div style={{ fontSize: '1.5rem', fontWeight: 700, color: '#7c3aed', lineHeight: 1.2 }}>
            {totalCausedGroups}
            <span style={{ fontSize: '0.85rem', fontWeight: 400, color: '#64748b' }}>
              &nbsp;/ {report.causeGroupDetails.length}
            </span>
          </div>
        </div>
        <div style={{ borderLeft: '1px solid #e9d5ff', height: 40 }} />
        <div>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Tổng sự cố có phân tích nguyên nhân</span>
          <div style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1a202c', lineHeight: 1.2 }}>
            {report.causeGroupDetails.reduce((acc, g) => acc + g.totalCount, 0)}
          </div>
        </div>
        <div style={{ marginLeft: 'auto', fontSize: '0.8rem', color: '#94a3b8' }}>
          <i className="fas fa-info-circle" style={{ marginRight: 4 }} />
          Dữ liệu từ phiếu phân tích sự cố (Tab 4A)
        </div>
      </div>

      {/* Group cards */}
      <div className={s.grid1}>
        {report.causeGroupDetails.map((group, idx) => (
          <CauseGroupCard key={group.groupKey} group={group} colorIndex={idx} />
        ))}
      </div>
    </div>
  );
};
