/**
 * Tab 4 — Thống kê sự cố theo nhóm loại sự cố
 *
 * Shows 11 collapsible group cards, each with a detail table.
 */
import React, { useState } from 'react';
import { MedicalIncidentReport, GroupDetail } from '../../../models/MedicalIncident';
import s from './shared.module.css';

interface Props {
  report: MedicalIncidentReport;
}

interface GroupCardProps {
  group: GroupDetail;
  index: number;
}

const GroupCard: React.FC<GroupCardProps> = ({ group, index }) => {
  const [open, setOpen] = useState(group.totalCount > 0);

  const nonZeroItems = group.items.filter((i) => i.count > 0);
  const hasData = group.totalCount > 0;

  return (
    <div className={s.groupCard}>
      <div className={s.groupHeader} onClick={() => setOpen((p) => !p)}>
        <div className={s.groupHeaderLeft}>
          <span
            style={{
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              width: 26, height: 26, borderRadius: '50%',
              background: hasData ? 'var(--color-primary, #0066cc)' : '#e2e8f0',
              color: hasData ? '#fff' : '#94a3b8',
              fontSize: '0.75rem', fontWeight: 700,
            }}
          >
            {index + 1}
          </span>
          <span className={s.groupLabel}>{group.groupLabel}</span>
          {hasData && (
            <span className={s.groupBadge}>{group.totalCount}</span>
          )}
          {!hasData && (
            <span
              style={{
                fontSize: '0.72rem', color: '#94a3b8',
                background: '#f1f5f9', borderRadius: 999, padding: '2px 8px',
              }}
            >
              Không có sự cố
            </span>
          )}
        </div>
        <i className={`fas fa-chevron-down ${s.groupChevron} ${open ? s.open : ''}`} />
      </div>

      {open && (
        <>
          {nonZeroItems.length === 0 ? (
            <div className={s.emptyState}>
              <i className="fas fa-check-circle" style={{ color: '#10b981', marginRight: 6 }} />
              Không ghi nhận sự cố trong nhóm này
            </div>
          ) : (
            <table className={s.detailTable}>
              <thead>
                <tr>
                  <th>Loại sự cố</th>
                  <th style={{ textAlign: 'right', width: 80 }}>Số ca</th>
                </tr>
              </thead>
              <tbody>
                {group.items.map((item) => (
                  <tr key={item.key}>
                    <td>{item.label}</td>
                    <td className={`${s.countCell} ${item.count === 0 ? s.zeroCount : ''}`}>
                      {item.count === 0 ? '–' : item.count}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </>
      )}
    </div>
  );
};

export const Tab4ByTypeGroup: React.FC<Props> = ({ report }) => {
  const totalWithIncidents = report.incidentTypeGroupDetails.filter((g) => g.totalCount > 0).length;

  return (
    <div>
      {/* Summary header */}
      <div
        style={{
          display: 'flex', alignItems: 'center', gap: 16, marginBottom: 16,
          padding: '12px 16px',
          background: '#f0f7ff',
          borderRadius: 10,
          border: '1px solid #bfdbfe',
          flexWrap: 'wrap',
        }}
      >
        <div>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Nhóm có sự cố</span>
          <div style={{ fontSize: '1.5rem', fontWeight: 700, color: '#0066cc', lineHeight: 1.2 }}>
            {totalWithIncidents}
            <span style={{ fontSize: '0.85rem', fontWeight: 400, color: '#64748b' }}>
              &nbsp;/ {report.incidentTypeGroupDetails.length}
            </span>
          </div>
        </div>
        <div style={{ borderLeft: '1px solid #bfdbfe', height: 40 }} />
        <div>
          <span style={{ fontSize: '0.8rem', color: '#64748b' }}>Tổng sự cố có phân tích nhóm</span>
          <div style={{ fontSize: '1.5rem', fontWeight: 700, color: '#1a202c', lineHeight: 1.2 }}>
            {report.incidentTypeGroupDetails.reduce((s, g) => s + g.totalCount, 0)}
          </div>
        </div>
        <div style={{ marginLeft: 'auto', fontSize: '0.8rem', color: '#94a3b8' }}>
          <i className="fas fa-info-circle" style={{ marginRight: 4 }} />
          Nhấn vào nhóm để xem chi tiết
        </div>
      </div>

      {/* Group cards */}
      <div className={s.grid1}>
        {report.incidentTypeGroupDetails.map((group, idx) => (
          <GroupCard key={group.groupKey} group={group} index={idx} />
        ))}
      </div>
    </div>
  );
};
