import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useAppDispatch } from '../../store/hooks';
import { addToast } from '../../store/slices/uiSlice';
import { useResponsive } from '../../hooks/useResponsive';
import { useMinLoadingTime } from '../../hooks/useMinLoadingTime';
import { useMedicalIncidentPermissions } from '../../hooks/useMedicalIncidentPermissions';
import { medicalIncidentService } from '../../services/medicalIncidents/medicalIncidentService';
import {
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
} from '../../models/MedicalIncident';
import { MedicalIncidentReportFiltersBar } from './components/MedicalIncidentReportFilters';
import { ReportPageSkeleton } from './components/ReportPageSkeleton';
import { Tab1ReportedStats }     from './components/Tab1_ReportedStats';
import { Tab2Analysis }          from './components/Tab2_Analysis';
import { Tab3Assessment }        from './components/Tab3_Assessment';
import { Tab4ByTypeGroup }       from './components/Tab4_ByTypeGroup';
import { Tab5ByCauseGroup }      from './components/Tab5_ByCauseGroup';
import styles from './MedicalIncidentReportPage.module.css';


import { Tabs, Button, StatsCard, StatsCardsGrid, TableCard } from '@linm-soft-org/linm-web-common-components';
import { ErpFilterCardHeader } from '../../components/layout/ErpFilterCardHeader';
import { currentYearDateRange } from '../../hooks/useReportPeriodFilter';

function getDefaultFilters(): MedicalIncidentReportFilters {
  const { dateFrom, dateTo } = currentYearDateRange();
  return { dateFrom, dateTo };
}

const MedicalIncidentReportPage: React.FC = () => {
  const dispatch       = useAppDispatch();
  const { isMobile }  = useResponsive();
  const { isReporterScope } = useMedicalIncidentPermissions();

  const [filters,   setFilters]   = useState<MedicalIncidentReportFilters>(getDefaultFilters);
  const [report,    setReport]    = useState<MedicalIncidentReport | null>(null);
  const [loading,   setLoading]   = useState(false);
  const [activeTab, setActiveTab] = useState('tab1');

  // Keep skeleton visible for at least 300 ms to avoid flash-of-loading.
  const showLoading = useMinLoadingTime(loading);

  const loadCancelRef = useRef(false);

  const loadReport = useCallback(async (f: MedicalIncidentReportFilters) => {
    loadCancelRef.current = false;
    setLoading(true);
    try {
      const data = await medicalIncidentService.getReport(f);
      if (loadCancelRef.current) return;
      setReport(data);
    } catch {
      if (!loadCancelRef.current) dispatch(addToast({ type: 'error', message: 'Không thể tải dữ liệu báo cáo. Vui lòng thử lại.' }));
    } finally {
      if (!loadCancelRef.current) setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = setTimeout(() => loadReport(filters), 0);
    return () => { clearTimeout(t); loadCancelRef.current = true; };
  }, [loadReport, filters]);

  const handleSearchFilters = (f: MedicalIncidentReportFilters) => setFilters(f);
  const handleClearFilters  = () => setFilters(getDefaultFilters());

  // ── Period label for stats card subtitle ─────────────────────────────────
  const periodLabel = (() => {
    const from = filters.dateFrom ? new Date(filters.dateFrom).toLocaleDateString('vi-VN') : '';
    const to   = filters.dateTo   ? new Date(filters.dateTo).toLocaleDateString('vi-VN')   : '';
    if (from && to) return `${from} – ${to}`;
    if (from)       return `Từ ${from}`;
    if (to)         return `Đến ${to}`;
    return 'Tất cả';
  })();

  const tabs = [
    {
      id: 'tab1',
      label: 'Thống kê SCYK',
      icon: 'fas fa-chart-bar',
      content: report ? <Tab1ReportedStats report={report} filters={filters} /> : null,
    },
    {
      id: 'tab2',
      label: 'Thống kê phân tích',
      icon: 'fas fa-chart-pie',
      content: report ? <Tab2Analysis report={report} filters={filters} /> : null,
    },
    {
      id: 'tab3',
      label: 'Thống kê đánh giá',
      icon: 'fas fa-star-half-alt',
      content: report ? <Tab3Assessment report={report} filters={filters} /> : null,
    },
    {
      id: 'tab4',
      label: 'Theo nhóm SC',
      icon: 'fas fa-layer-group',
      content: report ? <Tab4ByTypeGroup report={report} /> : null,
    },
    {
      id: 'tab5',
      label: 'Theo nhóm nguyên nhân',
      icon: 'fas fa-sitemap',
      content: report ? <Tab5ByCauseGroup report={report} /> : null,
    },
  ];

  return (
    <div className={styles.page} data-report-list-page data-lin-list-layout="erp-filter-bar">
      {/* Header: title left, refresh button right — single compact row */}
      <div className={styles.pageHeader}>
        <h1 className={styles.title}>
          <i className="fas fa-chart-bar" />
          {!isMobile && ' Báo Cáo Thống Kê Sự Cố Y Khoa'}
        </h1>
        <div className={styles.headerActions}>
          <Button variant="secondary" size="sm" onClick={() => loadReport(filters)} disabled={loading}>
            <i className="fas fa-sync-alt" />
            {!isMobile && ' Làm mới'}
          </Button>
        </div>
      </div>

      {isReporterScope && (
        <div className={styles.roleBanner}>
          <i className="fas fa-user-shield" />
          <span>Báo cáo thống kê <strong>sự cố do bạn tạo</strong>.</span>
        </div>
      )}

      {/* ── Filter + summary card ────────────────────────────────────────── */}
      <TableCard
        header={
          <ErpFilterCardHeader title="Kỳ báo cáo" testIdPrefix="medical-incident-report">
            <MedicalIncidentReportFiltersBar
              filters={filters}
              onSearch={handleSearchFilters}
              onClear={handleClearFilters}
              loading={showLoading}
            />
          </ErpFilterCardHeader>
        }
      >
        <div className={styles.statsWrapper}>
          <StatsCardsGrid>
            <StatsCard
              label={`Tổng sự cố${periodLabel ? ` · ${periodLabel}` : ''}`}
              value={report?.totalCount ?? 0}
              icon="fas fa-hospital-user"
              variant="primary"
              loading={showLoading}
            />
          </StatsCardsGrid>
        </div>
      </TableCard>

      {/* ── Content: skeleton while loading, tabs when ready, error if failed ── */}
      {showLoading && <ReportPageSkeleton />}

      {!showLoading && !report && (
        <div className={styles.errorWrapper}>
          <i className="fas fa-exclamation-circle" />
          <span>Không có dữ liệu. Vui lòng thử lại.</span>
        </div>
      )}

      {!showLoading && report && (
        <div className={styles.tabCard}>
          <Tabs
            tabs={tabs}
            activeTab={activeTab}
            onTabChange={setActiveTab}
            variant="default"
            sticky
          />
        </div>
      )}
    </div>
  );
};

export default MedicalIncidentReportPage;
